final languageProvider = StateNotifierProvider<LanguageNotifier, String>((ref) {
  return LanguageNotifier();
});

class LanguageNotifier extends StateNotifier<String> {
  final _storage = const FlutterSecureStorage();
  static const _langKey = 'app_language';

  LanguageNotifier() : super('en') {
    _loadLanguage();
  }

  Future<void> _loadLanguage() async {
    final savedLang = await _storage.read(key: _langKey);
    if (savedLang != null && savedLang.isNotEmpty) {
      state = savedLang;
    }
  }

  Future<void> setLanguage(String code, {bool syncBackend = true}) async {
    if (code.isEmpty) return;
    state = code;
    await _storage.write(key: _langKey, value: code);

    if (syncBackend) {
      try {
        await ApiClient().dio.put('auth/language', data: {'language': code});
      } catch (_) {
        // Non-blocking if offline or unauthenticated
      }
    }
  }
}

